import 'package:flutter/material.dart';
import '../core/app_state.dart';
import '../models/models.dart';
import '../widgets/app_components.dart';

 class ContactsScreen extends StatelessWidget { final AppState state; const ContactsScreen({super.key, required this.state}); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Trusted people'), actions: [IconButton(onPressed: () => _add(context), icon: const Icon(Icons.add))]), body: state.contacts.isEmpty ? const EmptyState(icon: Icons.people_outline, title: 'No trusted people yet', detail: 'Add someone you trust so they can receive check-ins and SOS alerts.') : ListView(padding: const EdgeInsets.all(20), children: [Text('These people can receive your safety updates.', style: Theme.of(context).textTheme.bodyMedium), const SizedBox(height: 16), ...state.contacts.map((contact) => Card(child: ListTile(leading: CircleAvatar(child: Text(contact.name[0])), title: Text(contact.name), subtitle: Text(contact.phone), trailing: const Icon(Icons.verified_user_outlined, color: Colors.green))))])); void _add(BuildContext context) { final name = TextEditingController(); final phone = TextEditingController(); showDialog(context: context, builder: (_) => AlertDialog(title: const Text('Add trusted person'), content: Column(mainAxisSize: MainAxisSize.min, children: [TextField(controller: name, decoration: const InputDecoration(labelText: 'Name')), TextField(controller: phone, keyboardType: TextInputType.phone, decoration: const InputDecoration(labelText: 'Phone number'))]), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')), FilledButton(onPressed: () { if (name.text.trim().isNotEmpty && phone.text.trim().isNotEmpty) state.addContact(SafetyContact(id: name.text.trim(), name: name.text.trim(), phone: phone.text.trim())); Navigator.pop(context); }, child: const Text('Add'))])); } }
